#include <iostream>
#include <string>
#include <string_view>

// GradeBook class demonstrates a member function with a parameter
class GradeBook {
public:
    // displayMessage outputs a customized welcome banner.
    // Marked const because it does not alter the GradeBook instance.
    void displayMessage(std::string_view courseName) const {
        std::cout << "Welcome to the grade book for\n" 
                  << courseName << "!\n";
    }
};

int main() {
    GradeBook myGradeBook;
    std::string nameOfCourse;

    std::cout << "Please enter the course name:\n";
    // Read the complete line including spaces
    if (std::getline(std::cin, nameOfCourse)) {
        std::cout << "\n";
        myGradeBook.displayMessage(nameOfCourse);
    }

    return 0;
}
